import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: API 권한이 '로그인 사용자'라서 임직원, 예산·회계 담당자 역할을 허용한다.
const ALLOWED_STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];

@Controller('api/v1')
export class FnSfr03208Controller {
  @Post('/purchase-requests/approval-result')
  @HttpCode(200)
  async reflectPurchaseRequestApprovalResult(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const rawId = data['approvalDocumentId'];
    const status = data['approvalStatus'];
    if (
      (typeof rawId !== 'number' && typeof rawId !== 'string') ||
      !/^\d+$/.test(String(rawId))
    ) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서를 확인해 주세요.');
    }
    if (typeof status !== 'string' || !ALLOWED_STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재 상태를 확인해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `UPDATE purchase_request
            SET approval_status = :status,
                updated_at = now()
          WHERE approval_document_id = CAST(:approvalDocumentId AS bigint)
        RETURNING purchase_request_id AS "purchaseRequestId",
                  approval_status AS "approvalStatus"`,
        { status, approvalDocumentId: String(rawId) },
      );
      if (rows.length === 0) {
        throw new ApiError(
          404,
          'PURCHASE_REQUEST_NOT_FOUND',
          '결재문서에 연결된 품의서가 없습니다.',
        );
      }
      return rows[0];
    });
  }
}

