import { useState } from 'react';
import { call, Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, RefName, Select, Tiles } from '../kit';
import type { PageProps, Row } from '../kit';

const STATUSES: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

export default function FnSfr03208Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [results, setResults] = useState<Row[]>([]);
  const [approvalDocumentId, setApprovalDocumentId] = useState<number | string>('');
  const [approvalStatus, setApprovalStatus] = useState('');

  function openForm() {
    setApprovalDocumentId('');
    setApprovalStatus('');
    setOpen(true);
  }

  async function submit() {
    if (approvalDocumentId === '' || !approvalStatus) {
      throw new Error('결재문서와 결재 상태를 입력해 주세요.');
    }
    const result = await call('POST', '/purchase-requests/approval-result', role, {
      approvalDocumentId,
      approvalStatus,
    });
    setResults([result, ...results]);
    setOpen(false);
    notify('결재 결과를 품의서에 반영했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>반영 건수</h2>
        <Tiles items={[['이 화면에서 반영', results.length]]} />
      </section>
      <section className="box span-8">
        <h2>반영 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={openForm}>결재 결과 반영</button>
        </Band>
        <DataTable
          rows={results}
          empty="반영한 결재 결과가 없습니다."
          columns={[
            {
              key: 'purchaseRequestId',
              label: '품의서',
              render: (row) => (
                <RefName table="purchase_request" role={role} value={row.purchaseRequestId} />
              ),
            },
            {
              key: 'approvalStatus',
              label: '결재 상태',
              render: (row) => <Badge value={row.approvalStatus} />,
            },
          ]}
        />
      </section>
      {open && (
        <Drawer title="결재 결과 반영" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="반영">
            <Field label="결재문서" required>
              <LookupSelect
                table="approval_document"
                role={role}
                value={approvalDocumentId}
                onChange={setApprovalDocumentId}
              />
            </Field>
            <Field label="결재 상태" required>
              <Select value={approvalStatus} onChange={setApprovalStatus} options={STATUSES} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
